import{_ as r,o as a,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"О Sapphire Star Codex","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ru/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ru/others/"}],["meta",{"property":"og:title","content":"О Sapphire Star Codex | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Данные Monster Hunter и подбор брони для Wilds, Rise с Sunbreak и World с Iceborne."}]]},"headers":[],"relativePath":"ru/others/index.md","filePath":"ru/others/index.md"}'),n={name:"ru/others/index.md"};function i(p,e,l,h,s,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="о-sapphire-star-codex" tabindex="-1">О Sapphire Star Codex <a class="header-anchor" href="#о-sapphire-star-codex" aria-label="Permalink to &quot;О Sapphire Star Codex&quot;">​</a></h1><h2 id="о-проекте" tabindex="-1">О проекте <a class="header-anchor" href="#о-проекте" aria-label="Permalink to &quot;О проекте&quot;">​</a></h2><p>Sapphire Star Codex объединяет данные Monster Hunter и поиск комплектов брони. Приложение независимо разрабатывает и поддерживает автор <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a>. Оно бесплатно, без рекламы и платных функций.</p><p>Версия Android доступна в <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a>, HarmonyOS — в <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. Версия iOS готовится к выпуску. Ссылки находятся в разделе <a href="./../#download">загрузки</a>; доступность зависит от региона и устройства.</p><h2 id="обратная-связь-и-участие" tabindex="-1">Обратная связь и участие <a class="header-anchor" href="#обратная-связь-и-участие" aria-label="Permalink to &quot;Обратная связь и участие&quot;">​</a></h2><p>Сообщая об ошибке, укажите игру, запись, язык, шаги и проверяемый источник. Скрывайте личные данные на снимках экрана. Контакт: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Также полезны рекомендации приложения, исправления и <a href="./../support/">добровольная поддержка</a>.</p><h2 id="источники-и-права" tabindex="-1">Источники и права <a class="header-anchor" href="#источники-и-права" aria-label="Permalink to &quot;Источники и права&quot;">​</a></h2><p>Данные получены из <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>, <a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> и файлов игр и сверяются с источниками сообщества. Возможны ошибки и пропуски. Названия, изображения и данные Monster Hunter принадлежат CAPCOM; требования об удалении будут выполнены. Лицензия MIT адаптированного кода Pocket Gallery не распространяется на изображения и данные игр.</p>',8)])])}const u=r(n,[["render",i]]);export{f as __pageData,u as default};
